values.content:
=Extract meeting details from this email. Return ONLY valid JSON, no markdown, no explanation.

Today's reference date (the date this email was sent): {{ $json.internalDate }}

Subject: {{ $json.Subject }}
Snippet: {{ $json.snippet }}
From: {{ $json.From }}

Calculate "resolved_date" by finding the next occurrence of the mentioned day (e.g. "Thursday") AFTER the reference date above.

{
  "proposed_day": "...",
  "resolved_date": "YYYY-MM-DD",
  "start_time": "HH:MM",
  "end_time": "HH:MM",
  "requester_timezone_hint": "...",
  "requester_email": "..."
}
For requester_timezone_hint, normalize to a standard abbreviation (EST, PST, CST, MST, GMT, CET, IST, JST, etc.) even if the email uses a full name like "Eastern time" or "Pacific". If no timezone is mentioned, return null.

parameters.jsCode:
// Parse Gemini's raw JSON-string output
const raw = $input.first().json.content.parts[0].text;
const data = JSON.parse(raw);

// --- YOUR timezone (Marvin) — set this once, hardcoded ---
const MY_UTC_OFFSET = 8;

// Named timezone abbreviations -> UTC offset (add more as needed)
const NAMED_ZONE_OFFSETS = {
  'EST': -5, 'EDT': -4, 'EASTERN': -5, 'EASTERN TIME': -5,
  'CST': -6, 'CDT': -5, 'CENTRAL': -6, 'CENTRAL TIME': -6,
  'MST': -7, 'MDT': -6, 'MOUNTAIN': -7, 'MOUNTAIN TIME': -7,
  'PST': -8, 'PDT': -7, 'PACIFIC': -8, 'PACIFIC TIME': -8,
  'GMT': 0, 'UTC': 0,
  'CET': 1, 'CEST': 2,
  'IST': 5.5,
  'JST': 9,
  'AEST': 10
};

const hint = (data.requester_timezone_hint || '').trim().toUpperCase();
let theirUtcOffset;
let zoneWasRecognized = false;

if (NAMED_ZONE_OFFSETS.hasOwnProperty(hint)) {
  theirUtcOffset = NAMED_ZONE_OFFSETS[hint];
  zoneWasRecognized = true;
} else {
  const offsetMatch = hint.match(/GMT([+-]\d+)/i);
  if (offsetMatch) {
    theirUtcOffset = parseInt(offsetMatch[1]);
    zoneWasRecognized = true;
  } else {
    theirUtcOffset = MY_UTC_OFFSET;
  }
}

const theirOffsetStr = `UTC${theirUtcOffset >= 0 ? '+' : ''}${theirUtcOffset}`;
const theirStart = DateTime.fromISO(`${data.resolved_date}T${data.start_time}:00`, { zone: theirOffsetStr });
const theirEnd = DateTime.fromISO(`${data.resolved_date}T${data.end_time}:00`, { zone: theirOffsetStr });

const myOffsetStr = `UTC${MY_UTC_OFFSET >= 0 ? '+' : ''}${MY_UTC_OFFSET}`;
const myStart = theirStart.setZone(myOffsetStr);
const myEnd = theirEnd.setZone(myOffsetStr);

// --- Separate business-hour windows for each side ---
const MY_BUSINESS_START = 20; // 8pm (your night shift)
const MY_BUSINESS_END = 6;    // 6am next day

const THEIR_BUSINESS_START = 8;  // 8am — normal client day
const THEIR_BUSINESS_END = 20;   // 8pm

function isWithinOvernightHours(hour, start, end) {
  if (start > end) {
    // wraps past midnight (like yours)
    return hour >= start || hour < end;
  }
  // normal same-day range (like theirs)
  return hour >= start && hour < end;
}

const theirHoursOk = isWithinOvernightHours(theirStart.hour, THEIR_BUSINESS_START, THEIR_BUSINESS_END)
                   && isWithinOvernightHours(theirEnd.hour, THEIR_BUSINESS_START, THEIR_BUSINESS_END);
const myHoursOk = isWithinOvernightHours(myStart.hour, MY_BUSINESS_START, MY_BUSINESS_END)
                && isWithinOvernightHours(myEnd.hour, MY_BUSINESS_START, MY_BUSINESS_END);

const withinHours = theirHoursOk && myHoursOk;

return {
  json: {
    ...data,
    message_id: $('Gmail Trigger').item.json.id,
    timezone_was_missing: !zoneWasRecognized,
    their_start_local: theirStart.toISO(),
    their_end_local: theirEnd.toISO(),
    my_start_local: myStart.toISO(),
    my_end_local: myEnd.toISO(),
    their_hours_ok: theirHoursOk,
    my_hours_ok: myHoursOk,
    within_business_hours: withinHours,
    needs_review: !withinHours || !zoneWasRecognized
  }
};

additionalFields.description:
=Auto-booked via n8n.
Requester: {{ $json.requester_email }}
Proposed timezone: {{ $json.requester_timezone_hint }}
Their local time: {{ $json.their_start_local }} – {{ $json.their_end_local }}

parameters.jsCode:
const data = $input.first().json;

const MY_UTC_OFFSET = 8;
const myOffsetStr = `UTC+${MY_UTC_OFFSET}`;

const NAMED_ZONE_OFFSETS = {
  'EST': -5, 'EDT': -4,
  'CST': -6, 'CDT': -5,
  'MST': -7, 'MDT': -6,
  'PST': -8, 'PDT': -7,
  'GMT': 0, 'UTC': 0,
  'CET': 1, 'CEST': 2,
  'IST': 5.5,
  'JST': 9,
  'AEST': 10
};

const hint = (data.requester_timezone_hint || '').trim().toUpperCase();
const theirUtcOffset = NAMED_ZONE_OFFSETS.hasOwnProperty(hint) ? NAMED_ZONE_OFFSETS[hint] : MY_UTC_OFFSET;
const theirOffsetStr = `UTC${theirUtcOffset >= 0 ? '+' : ''}${theirUtcOffset}`;

// Base off the originally resolved date, then offer that day + next 2 days
const baseDate = DateTime.fromISO(data.resolved_date, { zone: myOffsetStr });
const candidateHours = [21, 23, 2] 

const slots = candidateHours.map((hour, i) => {
  const myStart = baseDate.plus({ days: i }).set({ hour, minute: 0, second: 0 });
  const myEnd = myStart.plus({ hours: 1 });
  const theirStart = myStart.setZone(theirOffsetStr);
  const theirEnd = myEnd.setZone(theirOffsetStr);
  return {
    my_start_iso: myStart.toISO(),
    my_end_iso: myEnd.toISO(),
    their_display: `${theirStart.toFormat('cccc, MMM d')} — ${theirStart.toFormat('h:mm a')} to ${theirEnd.toFormat('h:mm a')} (${data.requester_timezone_hint})`
  };
});

const slotListText = slots.map((s, i) => `${i + 1}. ${s.their_display}`).join('\n');

return {
  json: {
    ...data,
    alt_slots: slots,
    slot_list_text: slotListText
  }
};
